#include "pyslm/support_utils.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
#include <map>
#include <numeric>
#include <stdexcept>

namespace pyslm::support {
namespace {
constexpr double pi=3.1415926535897932384626433832795;
bool onSegment(Vec2 p,Vec2 a,Vec2 b){return std::abs((p.x-a.x)*(b.y-a.y)-(p.y-a.y)*(b.x-a.x))<1e-9&&p.x>=std::min(a.x,b.x)&&p.x<=std::max(a.x,b.x)&&p.y>=std::min(a.y,b.y)&&p.y<=std::max(a.y,b.y);}
bool contains(const Path&path,Vec2 p,bool boundary=true){if(path.size()<3)return false;bool result=false;for(std::size_t i=0,j=path.size()-1;i<path.size();j=i++){auto a=path[j],b=path[i];if(onSegment(p,a,b))return boundary;if((a.y>p.y)!=(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)result=!result;}return result;}
Mesh projected(Mesh mesh){for(auto&p:mesh.vertices)p.z=0.;return mesh;}
}

FaceAdjacency getAdjacentFaces(const Mesh&mesh){FaceAdjacency r;std::map<std::size_t,std::size_t>positions;auto add=[&](std::size_t a,std::size_t b){auto found=positions.find(a);if(found==positions.end()){positions[a]=r.size();r.push_back({a,{}});found=positions.find(a);}auto&n=r[found->second].second;if(std::find(n.begin(),n.end(),b)==n.end())n.push_back(b);};for(auto pair:meshFaceAdjacency(mesh)){add(pair[0],pair[1]);add(pair[1],pair[0]);}return r;}
std::vector<double> getSupportAngles(const Part&part,std::optional<Vec3>normal,bool connectivity){auto normals=meshFaceNormals(part.geometry());auto up=normal.value_or(Vec3{0,0,-1});std::vector<double>angles;for(auto n:normals)angles.push_back(std::acos(std::clamp(dot(up,n),-1.,1.))*180./pi);if(!connectivity)return angles;auto result=angles;for(auto&entry:getAdjacentFaces(part.geometry())){double sum=angles[entry.first];for(auto n:entry.second)sum+=angles[n];result[entry.first]=sum/static_cast<double>(entry.second.size()+1);}return result;}
std::vector<double> getFaceZProjectionWeight(const Mesh&mesh,bool connectivity){auto normals=meshFaceNormals(mesh);std::vector<double>result;for(auto n:normals)result.push_back(std::sqrt(1-n.z*n.z));if(connectivity)for(auto&entry:getAdjacentFaces(mesh)){double sum=result[entry.first];for(auto n:entry.second)sum+=result[n];result[entry.first]=sum/static_cast<double>(entry.second.size()+1);}return result;}
Mesh getOverhangMesh(const Part&part,double angle,bool connectivity){auto theta=getSupportAngles(part,Vec3{0,0,1},connectivity);std::vector<std::size_t>selected;for(std::size_t i=0;i<theta.size();++i)if(theta[i]>180.-angle)selected.push_back(i);return selectMeshFaces(part.geometry(),selected,true);}
std::vector<Mesh> getOverhangMeshes(const Part&part,double angle,bool connectivity){return splitMeshComponents(getOverhangMesh(part,angle,connectivity));}
double approximateSupportMomentArea(const Part&part,double angle){auto mesh=getOverhangMesh(part,angle);auto flat=projected(mesh);auto areas=meshFaceAreas(flat);double result=0;for(std::size_t i=0;i<mesh.faces.size();++i){auto f=mesh.faces[i];double z=(mesh.vertices[f[0]].z+mesh.vertices[f[1]].z+mesh.vertices[f[2]].z)/3.;result+=areas[i]*z;}return result;}
std::vector<double> getApproximateSupportArea(const Part&part,double angle,bool project){auto mesh=getOverhangMesh(part,angle);return meshFaceAreas(project?projected(std::move(mesh)):mesh);}
NumericMatrix approximateSupportMapByCentroid(const Part&part,double angle,bool includeVertices){auto mesh=getOverhangMesh(part,angle);Path3D coords;for(auto f:mesh.faces)coords.push_back((mesh.vertices[f[0]]+mesh.vertices[f[1]]+mesh.vertices[f[2]])/3.);if(includeVertices)coords.insert(coords.end(),mesh.vertices.begin(),mesh.vertices.end());std::vector<double>heights(coords.size());for(std::size_t i=0;i<coords.size();++i)if(auto hit=firstRayIntersection(part.geometry(),coords[i],{0,0,-1}))heights[i]=static_cast<float>(hit->z);NumericMatrix result;result.rows=result.cols=coords.size();result.values.resize(result.rows*result.cols);for(std::size_t r=0;r<result.rows;++r)for(std::size_t c=0;c<result.cols;++c)result.at(r,c)=std::abs(heights[r]-coords[c].z);return result;}
ProjectionSupportCost approximateProjectionSupportCost(const Part&part,double angle,bool includeVertices){ProjectionSupportCost result;result.heightMap=approximateSupportMapByCentroid(part,angle,includeVertices);auto areas=getApproximateSupportArea(part,angle,true);if(result.heightMap.cols!=areas.size()&&!areas.empty())throw std::invalid_argument("Original face area and centroid/vertex height map shapes cannot broadcast");for(std::size_t r=0;r<result.heightMap.rows;++r)for(std::size_t c=0;c<result.heightMap.cols;++c)result.cost+=areas[c]*result.heightMap.at(r,c);return result;}
NumericMatrix generateHeightMap(const Mesh&mesh,Vec3 up,double resolution,const Polygons&offset){if(resolution<=0)throw std::invalid_argument("Height-map resolution must be positive");auto bounds=meshBounds(mesh);Polygons polygons=offset.empty()?Polygons{generatePolygonBoundingBox(bounds)}:offset;Bounds2 box{std::numeric_limits<double>::infinity(),std::numeric_limits<double>::infinity(),-std::numeric_limits<double>::infinity(),-std::numeric_limits<double>::infinity()};for(auto&p:polygons)for(auto v:p.exterior){box[0]=std::min(box[0],v.x);box[1]=std::min(box[1],v.y);box[2]=std::max(box[2],v.x);box[3]=std::max(box[3],v.y);}NumericMatrix result;result.rows=static_cast<std::size_t>(std::ceil((box[2]-box[0])/resolution))+2;result.cols=static_cast<std::size_t>(std::ceil((box[3]-box[1])/resolution))+2;result.values.assign(result.rows*result.cols,-1.);auto pixelPolygons=polygons;for(auto&p:pixelPolygons){auto pixel=[&](Path&ring){for(auto&v:ring){v.x=std::nearbyint((v.x-box[0])/resolution);v.y=std::nearbyint((v.y-box[1])/resolution);}};pixel(p.exterior);for(auto&h:p.interiors)pixel(h);}for(std::size_t x=0;x<result.rows;++x)for(std::size_t y=0;y<result.cols;++y){Vec2 pixel{static_cast<double>(x),static_cast<double>(y)};bool valid=false;for(auto&p:pixelPolygons)if(contains(p.exterior,pixel)){bool hole=false;for(auto&ring:p.interiors)if(contains(ring,pixel)){hole=true;break;}if(!hole){valid=true;break;}}if(!valid)continue;auto px=static_cast<float>(static_cast<float>(x)*resolution),py=static_cast<float>(static_cast<float>(y)*resolution);px=static_cast<float>(px+box[0]+1e-5);py=static_cast<float>(py+box[1]+1e-5);if(auto hit=firstRayIntersection(mesh,{px,py,-1e5},up)){auto ix=static_cast<long long>(std::ceil((hit->x-box[0])/resolution)),iy=static_cast<long long>(std::ceil((hit->y-box[1])/resolution));if(ix>=0&&iy>=0&&ix<static_cast<long long>(result.rows)&&iy<static_cast<long long>(result.cols))result.at(static_cast<std::size_t>(ix),static_cast<std::size_t>(iy))=hit->z;}}return result;}
NumericMatrix generateHeightMap2(const Mesh&mesh,Vec3 up,double resolution,const Polygons&offset){return generateHeightMap(mesh,up,resolution,offset);}
} // namespace pyslm::support
